targets.rawSql:
SELECT COALESCE(AVG(avg_merge_time_days), 0)::numeric(10,1) as days
FROM v_team_pr_health_summary_30d
WHERE team IN (${team:singlequote});

SELECT COALESCE(AVG(avg_approvals), 0)::numeric(10,1) as avg_approvals
FROM v_team_pr_health_summary_30d
WHERE team IN (${team:singlequote});

SELECT COALESCE(SUM(prs_with_issues), 0) as prs_with_issues
FROM v_team_pr_health_summary_30d
WHERE team IN (${team:singlequote});

SELECT COALESCE(SUM(total_vulnerabilities), 0) as total_vulnerabilities
FROM v_team_vulnerabilities_total_latest
WHERE team IN (${team:singlequote});
